from fractions import Fraction
import math, random

def rdiv(z, s):
    if s == 0:
        return z
    d = 2 ** s
    if z >= 0:
        return (2 * z + d) // (2 * d)
    return -((2 * (-z) + d) // (2 * d))

def ref2(z, s):
    q = Fraction(z, 2 ** s)
    if q >= 0:
        return math.floor(q + Fraction(1, 2))
    return -math.floor(-q + Fraction(1, 2))

r = random.Random(7)
bad = 0
for _ in range(300000):
    z = r.randint(-10**7, 10**7)
    s = r.randint(0, 16)
    a = rdiv(z, s)
    b = ref2(z, s)
    if a != b:
        bad += 1
        if bad < 10:
            print("DIFF", z, s, a, b)
# exact tie cases
for z in range(-70, 71):
    for s in range(0, 5):
        if rdiv(z, s) != ref2(z, s):
            print("TIE DIFF", z, s, rdiv(z, s), ref2(z, s)); bad += 1
print("rounding mismatches:", bad)
PYEOF
